head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf90500";
scwin.SCREN_PROCS_TP_CD_01 = "01";  // 조회 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.SCREN_PROCS_TP_CD_03 = "03";  // 수정 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.chk_active = null;
scwin.chk_read_hidden = null;
scwin.panelWav = null;
scwin.timer = null;
scwin.dts_dscs_noti_alram = null;
scwin.grd_ds = null;
scwin.gDepCd = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "chk_active", attr: "__value", fn: function () { return "Y"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider
    try {
        $c.frame.Provider("/top").alram_on_off_val = "Y";
        scwin.setWave();
        setTimeout(async function(){ await scwin.search() }, 1000);
        scwin.timer = setInterval(async function(){ await scwin.search() }, 30000);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf90500.onpageload' }); }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
    try {
        if (scwin.timer) {
            clearInterval(scwin.timer);
            scwin.timer = null;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf90500.onpageunload" });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.gDepCd =$c.session.getUserInfo("depCd"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf90500' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.chk_active = $c.util.getComponent('chk_active');
        scwin.chk_read_hidden = $c.util.getComponent('chk_read_hidden');
        scwin.panelWav = $c.util.getComponent('panelWav');
        scwin.dts_dscs_noti_alram = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsDscsNotiAlram')) : $c.util.getComponent('dtsDscsNotiAlram');
        scwin.grd_ds = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('grdDs')) : $c.util.getComponent('grdDs');
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf90500.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf90500.img_Close_onclick' }); }
};

/**
 * @method
 * @name grd_List_ondblclick
 * @description grd_List 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_ondblclick = async function (row, colid) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider
    try {
        const noti_svc_seq = scwin.grd_ds.getCellData(row, "NOTI_SVC_SEQ");
        if (colid === "COL2") {
            const go_url = scwin.grd_ds.getCellData(row, "URL");
            if (go_url === "STF30001") {
                const STF30001_URL = "/dsclmgt/ULDSTF30001.gfm?src=JSP&cmd=C&isFnSrch=N";
                $c.frame.Provider("/top").Provider("../").GWinOpen("child01", STF30001_URL, "일정조회", 20, 10, 10, 20, "");
            } else {
                if (go_url === "STF08051A") {
                    const STF08051A_URL = "/etn/ULDSTF08051.gfm?isEaryRedmpt=Y";
                    $c.frame.Provider("/top").Provider("../").GWinOpen("child01", STF08051A_URL, "조기상환 ETN", 20, 10, 1024, 600, "");
                } else {
                    if (go_url.length > 0) {
                        $c.frame.Provider("/top").WinOpenP(go_url);
                    }
                }
            }
            if (noti_svc_seq.length > 0) {
                await scwin.viewCheck(noti_svc_seq);
            }
        } else {
            if (colid === "COL1") {
                if (scwin.grd_ds.getCellData(row, "READ_YN") === "N") {
                    $c.frame.Provider("/top").Provider("../").fn_noti_open(noti_svc_seq);
                    await scwin.viewCheck(noti_svc_seq);
                }
            } else {
                if (colid === "CHECK_COL") {
                    if (Number(scwin.grd_ds.getCellData(row, "TIME_SUM")) < 17) {
                        if (noti_svc_seq.length > 0) {
                            await scwin.viewCheck(noti_svc_seq);
                        }
                    }
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf90500.grd_List_ondblclick' }); }
};

/**
 * @method
 * @name dts_dscs_noti_alram_onloaderror
 * @description dts_dscs_noti_alram onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_dscs_noti_alram_onloaderror = function () {

    // alert('');
    // frame.CloseFrame();

};

/**
 * @method
 * @name dts_dscs_noti_alram_onloadcompleted
 * @description dts_dscs_noti_alram onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dscs_noti_alram_onloadcompleted = function (rowcount) {
    try {
        scwin.dsCopy();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf90500.dts_dscs_noti_alram_onloadcompleted" });
    }
};

/**
 * @method
 * @name chk_read_hidden_onclick
 * @description chk_read_hidden 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_read_hidden_onclick = function () {
    try {
        scwin.grdDsOrder();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf90500.chk_read_hidden_onclick' }); }
};

/**
 * @method
 * @name grd_ds_onfilter
 * @description grd_ds onfilter 이벤트
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.grd_ds_onfilter = function (row) {
    try {
        if (!scwin.chk_read_hidden.checked) {
            if ((scwin.grd_ds.getCellData(row, "READ_YN") === "Y" && scwin.grd_ds.getCellData(row, "STAT_CD_TYPE") === "C") || (scwin.grd_ds.getCellData(row, "STAT_CD_TYPE") === "B" && scwin.grd_ds.getCellData(row, "DEP_CHECK") === "N" && scwin.grd_ds.getCellData(row, "READ_YN") === "Y")) {
                return false;
            } else {
                if (scwin.grd_ds.getCellData(row, "STAT_CD_TYPE") === "B" && scwin.grd_ds.getCellData(row, "DEP_CHECK") === "Y") {
                    if (scwin.grd_ds.getCellData(row, "FORM_UPCLSS_CD") === "zz" && scwin.grd_ds.getCellData(row, "READ_YN") === "N" && scwin.grd_ds.getCellData(row, "COL2").indexOf("공시승인 지연") === -1) {
                        return true;
                    } else {
                        return false;
                    }
                } else {
                    return true;
                }
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf90500.grd_ds_onfilter" });
    }
};

/**
 * @method
 * @name grd_ds_onloadcompleted
 * @description grd_ds onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.grd_ds_onloadcompleted = function (rowcount) {

    // alert('grd_ds.OnLoadCompleted('+rowcount+')');

};

