    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, DEPT_CD, USR_ID"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, DEPT_CD, USR_ID", unresolved: "query_param:SCREN_PROCES_TP_CD,DEPT_CD,USR_ID" };
    const sbmOptions = {
        id: "tx_script_dts_dscs_noti_alram",
        method: "post",
