        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_dscs_noti_alram_onloaderror'] === 'function') ? scwin['dts_dscs_noti_alram_onloaderror'] : (typeof scwin['dts_dscs_noti_alram_onfail'] === 'function') ? scwin['dts_dscs_noti_alram_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_dscs_noti_alram_onloadcompleted'] === 'function') ? scwin['dts_dscs_noti_alram_onloadcompleted'] : ((typeof scwin['dts_dscs_noti_alram_onsuccess'] === 'function') ? scwin['dts_dscs_noti_alram_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsDscsNotiAlram'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf90500.tx_script_dts_dscs_noti_alram" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

