///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const url = "/notisvc.do?SCREN_ID=" + "ULDSTF90500.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_01 + "&method=getAlramList&inputMessageId=TBLD_DSCS_NOTI_ALRAM" + "&DEPT_CD=" + $c.session.getUserInfo("depCd") + "&USR_ID=" + $c.session.getUserInfo("id");

    await scwin.tx_script_dts_dscs_noti_alram();
};

/**
 * @method
 * @name viewCheck
 * @description view Check 처리
 * @param {*} noti_seq noti_seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewCheck = async function (noti_seq) {
    const url = "/notisvc.do?SCREN_ID=" + "ULDSTF90500.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_03 + "&method=viewCheck&inputMessageId=TBLD_DSCS_NOTI_ALRAM" + "&NOTI_SVC_SEQ=" + noti_seq + "&DEPT_CD=" + $c.session.getUserInfo("depCd") + "&USR_ID=" + $c.session.getUserInfo("id");

    await scwin.tx_script_dts_dscs_noti_alram();
};

/**
 * @method
 * @name chkAlert
 * @description chk Alert 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkAlert = function () {
    let read_yn = "";
    let dep_cd = "";
    let sound_yn = "";
    let isNotiYn = false;
    for (let i = scwin.dts_dscs_noti_alram.CountRow; i > 0; i--) {
        read_yn = scwin.dts_dscs_noti_alram.getCellData(i, "READ_YN");
        dep_cd = scwin.dts_dscs_noti_alram.getCellData(i, "DEP_CD");
        sound_yn = scwin.dts_dscs_noti_alram.getCellData(i, "SOUND_YN");
        if (read_yn === "N" && sound_yn === "Y" && dep_cd != null && scwin.gDepCd === dep_cd) {
            if (scwin.gDepCd === "4210") {
                isNotiYn = true;
                break;
            } else {
                if (scwin.gDepCd === "2430") {
                    scwin.playNotice();
                }
            }
        }
    }
    if (scwin.gDepCd === "4210") {
        if (isNotiYn) {
            scwin.playNotice();
        } else {
            scwin.stopNotice();
        }
    }
};

/**
 * @method
 * @name dsCopy
 * @description ds Copy 처리
 * @returns {void}
 * @hidden N
 */
scwin.dsCopy = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.FrameShow, $c.frame.Provider
    scwin.grd_ds.removeAll();
    (scwin.grd_ds && typeof scwin.grd_ds.setDataHeader === "function" && scwin.grd_ds.setDataHeader(scwin.dts_dscs_noti_alram.DataHeader));
    scwin.grd_ds.setJSON(scwin.dts_dscs_noti_alram.getRangeJSON(1, scwin.dts_dscs_noti_alram.CountRow, true));
    scwin.grd_ds.filter();
    if (scwin.chk_active.checked) {
        scwin.chkAlert();
        $c.frame.FrameShow("showna");
    }
    if (scwin.dts_dscs_noti_alram.CountRow > 0) {
        const no_count = scwin.grd_ds.getCellData(0, "NO_COUNT");
        if (no_count !== "0|0") {
            $c.frame.Provider("/top").fn_alram_msg(no_count);
            scwin.grd_ds.RowPosition = 0;
        } else {

        }
    } else {

    }
};

/**
 * @method
 * @name grdDsOrder
 * @description grd Ds Order 처리
 * @returns {void}
 * @hidden N
 */
scwin.grdDsOrder = function () {
    if (!scwin.chk_read_hidden.checked) {
        scwin.grd_ds.filter();
    } else {
        scwin.dsCopy();
    }
};

/**
 * @method
 * @name setWave
 * @description set Wave 처리
 * @returns {void}
 * @hidden N
 */
scwin.setWave = function () {
    if (scwin.gDepCd === "4210") {
        scwin.panelWav.setStyle("display", 'none');
        (($c.util.getComponent("panelWav")) && ($c.util.getComponent("panelWav")).setValue ? ($c.util.getComponent("panelWav")).setValue("<embed src='/common/alert.wav' name='alertWave' autostart='false' loop='true'>") : (($c.util.getComponent("panelWav")) ? (($c.util.getComponent("panelWav")).innerHTML = "<embed src='/common/alert.wav' name='alertWave' autostart='false' loop='true'>") : void ("<embed src='/common/alert.wav' name='alertWave' autostart='false' loop='true'>")));
    } else {
        if (scwin.gDepCd === "2430") {
            scwin.panelWav.setStyle("display", 'none');
